"""Generated by solo-to-scale; edit `templates/tools/goals.py` in the plugin, then run upgrade.

The goal tree, as data: founder/goals.json (founder-owned, behind the `decision` gate).

  North Star (goal + north_star metric) -> objectives (O1) per cycle (C1, 6 weeks before product-market fit)
  -> key results (O1.1, optionally proving a playbook stage gate) -> initiatives (I1, the key actions and epics)
  -> tickets (labels initiative:I1 and goal:O1).

Slices, epics and stories name an objective with "objective": "O1"; tickets carry the label `goal:O1`
(`tickets.py new --objective O1`) and, once initiatives exist, `initiative:I1` (`--initiative I1`, which implies
its objective). Sub-tickets inherit both. The `okr-plan` skill drafts the tree once the business model
(stage 3) is approved; the founder approves it by merging.

  python tools/goals.py check                       # is goals.json well formed, and do the links point somewhere?
  python tools/goals.py show                        # the whole tree, with progress
  python tools/goals.py update O1.1 --value 42 [--date YYYY-MM-DD] [--note TEXT]
                                                    # record a key result's (or `north-star`'s) new value via a PR
  python tools/goals.py cycle [--start YYYY-MM-DD] [--weeks 6]
                                                    # add the next cycle (C1, C2, ...) after the last one

A key result's progress is how far `current` has moved from `baseline` towards `target`, from 0 to 100%; a
target below the baseline (cut churn from 8% to 3%) counts down. An objective's progress is the mean of its
key results. Python 3 standard library only.
"""
from __future__ import annotations

import argparse
import datetime as dt
import json
import re
import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402

FILE = "founder/goals.json"
OBJECTIVE_ID = re.compile(r"^O\d{1,3}$")
KR_ID = re.compile(r"^(O\d{1,3})\.\d{1,3}$")
CYCLE_ID = re.compile(r"^C\d{1,3}$")
INITIATIVE_ID = re.compile(r"^I\d{1,4}$")
STATUSES = ("planned", "active", "achieved", "cancelled")
INITIATIVE_STATUSES = ("planned", "active", "done", "dropped")
LABEL_PREFIX = "goal:"
INITIATIVE_PREFIX = "initiative:"
NORTH_STAR = "north-star"
HISTORY_LIMIT = 60
CYCLE_WEEKS = 6
DRAFT_AFTER_STAGE = 3  # Business model and positioning: once it's Passed, the goal tree is drafted


def load(root: Path) -> dict[str, Any]:
    """goals.json as a dict; missing or unreadable means no goals yet."""
    try:
        data = json.loads(s.read(root / FILE) or "{}")
    except ValueError:
        return {"_error": f"{FILE} is not valid JSON"}
    return data if isinstance(data, dict) else {"_error": f"{FILE} must be a JSON object"}


def number(v: Any) -> float | None:
    if isinstance(v, bool) or v is None or v == "":
        return None
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def day(v: Any) -> dt.date | None:
    try:
        return dt.date.fromisoformat(str(v))
    except ValueError:
        return None


def kr_progress(kr: dict[str, Any]) -> float | None:
    """0..1 from baseline to target, or None when the numbers aren't set."""
    base, target, cur = number(kr.get("baseline")), number(kr.get("target")), number(kr.get("current"))
    if target is None or cur is None:
        return None
    base = 0.0 if base is None else base
    if target == base:
        return 1.0 if cur == target else 0.0
    return max(0.0, min(1.0, (cur - base) / (target - base)))


def objectives(data: dict[str, Any]) -> list[dict[str, Any]]:
    return [o for o in data.get("objectives") or [] if isinstance(o, dict)]


def ids(data: dict[str, Any]) -> set[str]:
    return {str(o.get("id")) for o in objectives(data)}


def cycles(data: dict[str, Any]) -> list[dict[str, Any]]:
    return [c for c in data.get("cycles") or [] if isinstance(c, dict)]


def initiatives(data: dict[str, Any]) -> list[dict[str, Any]]:
    return [i for i in data.get("initiatives") or [] if isinstance(i, dict)]


def kr_ids(data: dict[str, Any]) -> set[str]:
    return {str(kr.get("id")) for o in objectives(data) for kr in o.get("key_results") or [] if isinstance(kr, dict)}


def initiative_objective(data: dict[str, Any], iid: str) -> str:
    """The objective an initiative serves, through its key result; empty when unknown."""
    kr = next((str(i.get("key_result") or "") for i in initiatives(data) if str(i.get("id")) == iid), "")
    m = KR_ID.match(kr)
    return m.group(1) if m else ""


def live_initiatives(data: dict[str, Any]) -> list[dict[str, Any]]:
    """Planned or active initiatives under an active objective: the ones new tickets must name."""
    live = {str(o.get("id")) for o in active(data)}
    return [i for i in initiatives(data) if i.get("status", "active") in ("planned", "active")
            and initiative_objective(data, str(i.get("id"))) in live]


def problems(root: Path, data: dict[str, Any] | None = None) -> list[str]:
    """Everything wrong with goals.json and the links to it; empty when it's fine or absent."""
    data = load(root) if data is None else data
    if "_error" in data:
        return [data["_error"]]
    out: list[str] = []
    seen: set[str] = set()
    stage_nums = {x["stage"] for x in s.playbook(root)}
    ns = data.get("north_star")
    if ns not in (None, "", {}):
        if not isinstance(ns, dict):
            out.append(f"{FILE}: north_star must be an object (metric, unit, baseline, target, current, by)")
        else:
            if not str(ns.get("metric") or "").strip():
                out.append(f"{FILE}: north_star has no metric")
            for k in ("baseline", "target", "current"):
                if ns.get(k) not in (None, "") and number(ns.get(k)) is None:
                    out.append(f"{FILE}: north_star {k} must be a number")
            if number(ns.get("target")) is None:
                out.append(f"{FILE}: north_star has no target")
    cycle_ids: set[str] = set()
    for i, c in enumerate(data.get("cycles") or []):
        cid = str((c or {}).get("id") or "") if isinstance(c, dict) else ""
        where = f"{FILE}: cycle {cid or i + 1}"
        if not CYCLE_ID.match(cid):
            out.append(f"{where}: id must look like C1")
            continue
        if cid in cycle_ids:
            out.append(f"{where}: id used twice")
        cycle_ids.add(cid)
        start, end = day(c.get("start")), day(c.get("end"))
        if not start or not end:
            out.append(f"{where}: start and end must be YYYY-MM-DD")
        elif end <= start:
            out.append(f"{where}: ends before it starts")
    for i, o in enumerate(data.get("objectives") or []):
        if not isinstance(o, dict):
            out.append(f"{FILE}: objective {i + 1} is not an object")
            continue
        oid = str(o.get("id") or "")
        where = f"{FILE}: objective {oid or i + 1}"
        if not OBJECTIVE_ID.match(oid):
            out.append(f"{where}: id must look like O1")
        elif oid in seen:
            out.append(f"{where}: id used twice")
        seen.add(oid)
        if not str(o.get("title") or "").strip():
            out.append(f"{where}: has no title")
        if o.get("status", "active") not in STATUSES:
            out.append(f"{where}: status must be one of {', '.join(STATUSES)}")
        if o.get("owner") and str(o["owner"]) not in (*s.ROLES, "chief-of-staff", "founder"):
            out.append(f"{where}: owner {o['owner']!r} is not a role")
        if o.get("cycle") and str(o["cycle"]) not in cycle_ids:
            out.append(f"{where}: cycle {o['cycle']} isn't in cycles")
        for kr in o.get("key_results") or []:
            kid = str((kr or {}).get("id") or "") if isinstance(kr, dict) else ""
            m = KR_ID.match(kid)
            if not m or m.group(1) != oid:
                out.append(f"{where}: key result id {kid or '?'} must look like {oid or 'O1'}.1")
                continue
            if kid in seen:
                out.append(f"{where}: key result {kid} used twice")
            seen.add(kid)
            if not str(kr.get("metric") or "").strip():
                out.append(f"{where}: key result {kid} has no metric")
            for k in ("baseline", "target", "current"):
                if kr.get(k) not in (None, "") and number(kr.get(k)) is None:
                    out.append(f"{where}: key result {kid} {k} must be a number")
            if number(kr.get("target")) is None:
                out.append(f"{where}: key result {kid} has no target")
            if kr.get("stage") not in (None, ""):
                st = kr.get("stage")
                if isinstance(st, bool) or not isinstance(st, int) or (stage_nums and st not in stage_nums):
                    out.append(f"{where}: key result {kid} stage {st!r} must be a stage number in founder/playbook.md")
    krs_known = kr_ids(data)
    for i, x in enumerate(data.get("initiatives") or []):
        if not isinstance(x, dict):
            out.append(f"{FILE}: initiative {i + 1} is not an object")
            continue
        iid = str(x.get("id") or "")
        where = f"{FILE}: initiative {iid or i + 1}"
        if not INITIATIVE_ID.match(iid):
            out.append(f"{where}: id must look like I1")
        elif iid in seen:
            out.append(f"{where}: id used twice")
        seen.add(iid)
        if not str(x.get("title") or "").strip():
            out.append(f"{where}: has no title")
        if str(x.get("key_result") or "") not in krs_known:
            out.append(f"{where}: key_result {x.get('key_result') or '?'} isn't a key result in {FILE}")
        if x.get("status", "active") not in INITIATIVE_STATUSES:
            out.append(f"{where}: status must be one of {', '.join(INITIATIVE_STATUSES)}")
        if x.get("owner") and str(x["owner"]) not in (*s.ROLES, "chief-of-staff", "founder"):
            out.append(f"{where}: owner {x['owner']!r} is not a role")
    known = ids(data)
    cfg = s.config(root)
    sl = s.slices(root, cfg)
    things = [("epic", code, ep) for code, ep in sl["epics"].items() if isinstance(ep, dict)]
    things += [("slice", x.get("id"), x) for x in sl["slices"] if isinstance(x, dict)]
    things += [("story", x.get("id"), x) for x in sl["stories"] if isinstance(x, dict)]
    for kind, name, x in things:
        ref = x.get("objective")
        if ref and str(ref) not in known:
            out.append(f"{cfg.get('slices_file') or 'founder/slices.json'}: {kind} {name} names objective {ref}, "
                       f"which {FILE} doesn't define")
    return out


def active(data: dict[str, Any]) -> list[dict[str, Any]]:
    return [o for o in objectives(data) if o.get("status", "active") == "active"]


def advice(data: dict[str, Any]) -> list[str]:
    """The method's shape, as advice that never fails the check: 2 or 3 objectives, 2 to 4 key results each."""
    out = []
    live = active(data)
    if len(live) > 3:
        out.append(f"{len(live)} active objectives: keep it to 2 or 3 so the cycle has a focus")
    for o in live:
        n = len([k for k in o.get("key_results") or [] if isinstance(k, dict)])
        if not 2 <= n <= 4:
            out.append(f"{o.get('id')} has {n} key results: aim for 2 to 4")
        if not any(initiative_objective(data, str(i.get("id"))) == o.get("id") for i in initiatives(data)):
            out.append(f"{o.get('id')} has no initiatives yet: add the key actions that move its key results")
    return out


def current_cycle(data: dict[str, Any], today: dt.date) -> dict[str, Any] | None:
    """The cycle today falls in; else the next one; else the last one."""
    cs = sorted(((day(c.get("start")), day(c.get("end")), c) for c in cycles(data)
                 if day(c.get("start")) and day(c.get("end"))), key=lambda x: x[0])
    now = next((c for a, b, c in cs if a <= today <= b), None)
    return now or next((c for a, _, c in cs if a > today), None) or (cs[-1][2] if cs else None)


def due(root: Path, data: dict[str, Any], today: dt.date) -> str:
    """What the goal tree needs next from the team, or empty: drafting after stage 3, or the next cycle."""
    stages = {x["stage"]: str(x.get("status", "")).lower() for x in s.playbook(root)}
    approved = stages.get(DRAFT_AFTER_STAGE) in ("passed", "deferred") or any(
        n > DRAFT_AFTER_STAGE and st in ("current", "passed") for n, st in stages.items())
    if approved and (not str(data.get("goal") or "").strip() or not objectives(data)):
        return ("draft: the business model (stage 3) is approved, so the North Star and the first cycle's "
                "objectives, key results and initiatives are due (okr-plan)")
    cur = current_cycle(data, today)
    if cur and day(cur.get("end")) and day(cur["end"]) < today and active(data):
        return (f"review: cycle {cur.get('id')} ended on {cur.get('end')}; score it and draft the next one "
                "(okr-plan, then goals.py cycle)")
    return ""


def kr_view(kr: dict[str, Any], owner: str, stages: dict[int, dict[str, Any]]) -> dict[str, Any]:
    hist = [h for h in kr.get("history") or [] if isinstance(h, dict) and number(h.get("value")) is not None]
    st = kr.get("stage") if isinstance(kr.get("stage"), int) and not isinstance(kr.get("stage"), bool) else None
    return {"id": str(kr.get("id", "")), "metric": str(kr.get("metric", "")), "unit": str(kr.get("unit", "")),
            "baseline": number(kr.get("baseline")), "target": number(kr.get("target")),
            "current": number(kr.get("current")), "owner": str(kr.get("owner") or owner or ""),
            "updated": str(kr.get("updated", "")), "progress": kr_progress(kr),
            "stage": {"stage": st, "name": str(stages.get(st, {}).get("name", "")),
                      "status": str(stages.get(st, {}).get("status", ""))} if st else None,
            "history": [{"date": str(h.get("date", "")), "value": number(h.get("value"))} for h in hist][-HISTORY_LIMIT:]}


def build(root: Path, today: dt.date | None = None) -> dict[str, Any]:
    """What the dashboard and the portfolio show: the whole tree, North Star to initiatives, with progress."""
    today = today or dt.date.today()
    data = load(root)
    cfg = s.config(root)
    sl = s.slices(root, cfg)
    stages = {x["stage"]: x for x in s.playbook(root)}
    cyc = {str(c.get("id")): c for c in cycles(data)}
    inits = initiatives(data)
    out_objs = []
    for o in objectives(data):
        krs = [kr_view(kr, str(o.get("owner") or ""), stages) for kr in o.get("key_results") or [] if isinstance(kr, dict)]
        known = [k["progress"] for k in krs if k["progress"] is not None]
        oid = str(o.get("id", ""))
        linked = [x for x in sl["slices"] if isinstance(x, dict) and str(x.get("objective") or "") == oid]
        epics = sorted(code for code, ep in sl["epics"].items() if isinstance(ep, dict) and str(ep.get("objective") or "") == oid)
        c = cyc.get(str(o.get("cycle") or ""), {})
        mine = [{"id": str(i.get("id", "")), "title": str(i.get("title", "")), "key_result": str(i.get("key_result", "")),
                 "owner": str(i.get("owner") or ""), "status": str(i.get("status", "active")), "epic": str(i.get("epic") or "")}
                for i in inits if initiative_objective(data, str(i.get("id"))) == oid]
        out_objs.append({
            "id": oid, "title": str(o.get("title", "")), "quarter": str(o.get("quarter", "")),
            "cycle": str(o.get("cycle") or ""), "start": str(c.get("start", "")), "end": str(c.get("end", "")),
            "owner": str(o.get("owner", "")), "status": str(o.get("status", "active")), "why": str(o.get("why", "")),
            "progress": round(sum(known) / len(known), 4) if known else None, "key_results": krs,
            "initiatives": mine,
            "slices": {"total": len(linked), "done": sum(str(x.get("status", "")).lower() == "done" for x in linked),
                       "ids": [str(x.get("id", "")) for x in linked][:20]},
            "epics": epics,
        })
    ns = data.get("north_star") if isinstance(data.get("north_star"), dict) else None
    north = None
    if ns:
        north = kr_view({**ns, "id": NORTH_STAR}, "", stages)
        north["by"] = str(ns.get("by") or data.get("horizon") or "")
        del north["stage"]
    cur = current_cycle(data, today)
    return {"goal": str(data.get("goal") or ""), "horizon": str(data.get("horizon") or ""), "north_star": north,
            "cycles": [{"id": str(c.get("id", "")), "start": str(c.get("start", "")), "end": str(c.get("end", ""))}
                       for c in cycles(data)],
            "current_cycle": str(cur.get("id", "")) if cur else "",
            "objectives": out_objs, "due": due(root, data, today), "advice": advice(data),
            "problems": problems(root, data)}


def label(objective: str) -> str:
    return LABEL_PREFIX + objective


def objective_of(labels: list[str]) -> str:
    return next((lb[len(LABEL_PREFIX):] for lb in labels if lb.startswith(LABEL_PREFIX)), "")


def initiative_label(initiative: str) -> str:
    return INITIATIVE_PREFIX + initiative


def initiative_of(labels: list[str]) -> str:
    return next((lb[len(INITIATIVE_PREFIX):] for lb in labels if lb.startswith(INITIATIVE_PREFIX)), "")


def pct(p: float | None) -> str:
    return "not measured yet" if p is None else f"{round(100 * p)}%"


def cmd_check(a: argparse.Namespace) -> int:
    found = problems(a.root)
    if found:
        print("\n".join(found))
        return 1
    data = load(a.root)
    print(f"goals: OK ({len(objectives(data))} objectives)" if data else f"goals: no {FILE} yet")
    return 0


def cmd_show(a: argparse.Namespace) -> int:
    g = build(a.root)
    print(f"North Star: {g['goal'] or 'Open (the founder sets it in ' + FILE + ')'}")
    ns = g["north_star"]
    if ns:
        print(f"  {ns['metric']}: {ns['current']} of {ns['target']} {ns['unit']} (from {ns['baseline']}){' by ' + ns['by'] if ns['by'] else ''} {pct(ns['progress'])}")
    if g["current_cycle"]:
        c = next(c for c in g["cycles"] if c["id"] == g["current_cycle"])
        print(f"Cycle {c['id']}: {c['start']} to {c['end']}")
    for o in g["objectives"]:
        when = o["cycle"] or o["quarter"]
        print(f"\n{o['id']} {o['title']} [{o['status']}{', ' + when if when else ''}] {pct(o['progress'])}")
        for k in o["key_results"]:
            gate = f" (proves stage {k['stage']['stage']}: {k['stage']['status'] or 'not in the playbook'})" if k["stage"] else ""
            print(f"  {k['id']} {k['metric']}: {k['current']} of {k['target']} {k['unit']} (from {k['baseline']}) {pct(k['progress'])}{gate}")
            for i in o["initiatives"]:
                if i["key_result"] == k["id"]:
                    print(f"    {i['id']} {i['title']} [{i['status']}{', ' + i['owner'] if i['owner'] else ''}]")
    if g["due"]:
        print(f"\ndue: {g['due']}")
    for x in g["advice"]:
        print(f"advice: {x}")
    for p in g["problems"]:
        print(f"problem: {p}")
    return 1 if g["problems"] else 0


def cmd_update(a: argparse.Namespace) -> int:
    data = load(a.root)
    if "_error" in data:
        raise SystemExit(data["_error"])
    date = a.date or dt.date.today().isoformat()
    try:
        dt.date.fromisoformat(date)
    except ValueError:
        raise SystemExit(f"--date {date!r} must be YYYY-MM-DD") from None
    targets = [kr for o in objectives(data) for kr in o.get("key_results") or [] if isinstance(kr, dict)]
    if a.kr == NORTH_STAR and isinstance(data.get("north_star"), dict):
        targets = [{**data["north_star"], "id": NORTH_STAR}]
        data["north_star"] = targets[0]
    for kr in targets:
        if kr.get("id") == a.kr:
            kr["current"], kr["updated"] = a.value, date
            hist = [h for h in kr.get("history") or [] if isinstance(h, dict) and h.get("date") != date]
            hist.append({"date": date, "value": a.value, **({"note": a.note} if a.note else {})})
            kr["history"] = sorted(hist, key=lambda h: str(h.get("date")))[-HISTORY_LIMIT:]
            if a.kr == NORTH_STAR:
                kr.pop("id", None)
            save(a.root, data)
            print(f"{a.kr}: {a.value} on {date}. {FILE} is behind the decision gate: open a PR for the founder to merge.")
            return 0
    raise SystemExit(f"no key result {a.kr} in {FILE}")


def save(root: Path, data: dict[str, Any]) -> None:
    (root / FILE).write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8", newline="\n")


def cmd_cycle(a: argparse.Namespace) -> int:
    """Add the next cycle: it starts the day after the last one ends (or --start, or today) and runs --weeks."""
    data = load(a.root)
    if "_error" in data:
        raise SystemExit(data["_error"])
    cs = cycles(data)
    last = max((day(c.get("end")) for c in cs if day(c.get("end"))), default=None)
    start = day(a.start) if a.start else (last + dt.timedelta(days=1) if last else dt.date.today())
    if not start:
        raise SystemExit(f"--start {a.start!r} must be YYYY-MM-DD")
    if a.weeks < 1:
        raise SystemExit("--weeks must be at least 1")
    n = max((int(str(c.get("id"))[1:]) for c in cs if CYCLE_ID.match(str(c.get("id") or ""))), default=0) + 1
    new = {"id": f"C{n}", "start": start.isoformat(), "end": (start + dt.timedelta(weeks=a.weeks, days=-1)).isoformat()}
    data["cycles"] = [*data.get("cycles", []), new]
    save(a.root, data)
    print(f"{new['id']}: {new['start']} to {new['end']}. Give its objectives \"cycle\": \"{new['id']}\", then open a PR.")
    return 0


def main(argv: list[str] | None = None) -> int:
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    ap = argparse.ArgumentParser(description="The goal tree: North Star, objectives, key results, initiatives")
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("check", parents=[common])
    sub.add_parser("show", parents=[common])
    u = sub.add_parser("update", parents=[common])
    u.add_argument("kr")
    u.add_argument("--value", type=float, required=True)
    u.add_argument("--date", default="")
    u.add_argument("--note", default="")
    c = sub.add_parser("cycle", parents=[common])
    c.add_argument("--start", default="")
    c.add_argument("--weeks", type=int, default=CYCLE_WEEKS)
    a = ap.parse_args(argv)
    return {"check": cmd_check, "show": cmd_show, "update": cmd_update, "cycle": cmd_cycle}[a.cmd](a)


if __name__ == "__main__":
    sys.exit(main())
